"""X11 text commits using selection transfer, without temporary keyboard maps.

The selection owner survives the paste so the previous clipboard (including
binary/rich formats) remains available. All Xlib access belongs to one thread.
No clipboard contents are logged. Uses the existing python-xlib dependency.
"""
import asyncio
from concurrent.futures import Future
import logging
import os
import queue
import select
import subprocess
import threading
import time

from Xlib import X, Xatom, display, protocol, error

log = logging.getLogger("webrtc_input")
MAX_BYTES = 32 * 1024 * 1024
CHUNK_BYTES = 48 * 1024
_bridges = {}
_bridge_lock = threading.Lock()


class SelectionOwner:
    def __init__(self, display_name):
        self.display_name = display_name
        self.jobs = queue.Queue()
        self.state_lock = threading.Lock()
        self.closed = False
        self.ready = Future()
        threading.Thread(target=self._run, name="x11-text-selection", daemon=True).start()
        self.ready.result(timeout=5)

    def _run(self):
        try:
            self.d = display.Display(self.display_name)
            self.window = self.d.screen().root.create_window(
                0, 0, 1, 1, 0, X.CopyFromParent, event_mask=X.PropertyChangeMask)
            self.clipboard = self.atom("CLIPBOARD")
            self.targets = self.atom("TARGETS")
            self.incr = self.atom("INCR")
            self.read_property = self.atom("_SELKIES_TEXT_READ")
            self.data = {}
            self.transfers = {}
            self.pasting = False
            self.consumed = False
            self.ready.set_result(True)
        except Exception as exc:
            self.ready.set_exception(exc)
            return
        while True:
            try:
                job = self.jobs.get_nowait()
            except queue.Empty:
                job = None
            if job:
                text, result = job
                try:
                    self._commit(text)
                    result.set_result(True)
                except Exception as exc:
                    result.set_exception(exc)
            try:
                self._event(time.monotonic() + .05)
                now = time.monotonic()
                self.transfers = {k: v for k, v in self.transfers.items() if v[5] > now}
            except error.ConnectionClosedError:
                # An X server recovery invalidates every resource on this connection.
                with _bridge_lock:
                    _bridges.pop(self.display_name, None)
                with self.state_lock:
                    self.closed = True
                    while not self.jobs.empty():
                        self.jobs.get_nowait()[1].set_exception(RuntimeError("X display disconnected"))
                return
            except Exception:
                log.warning("X11 selection service event failed", exc_info=True)

    def atom(self, name):
        return self.d.intern_atom(name)

    def owner(self):
        owner = self.d.get_selection_owner(self.clipboard)
        return getattr(owner, "id", 0)

    def _event(self, deadline):
        if not self.d.pending_events():
            select.select([self.d.fileno()], [], [], max(0, min(.05, deadline - time.monotonic())))
        if not self.d.pending_events():
            return None
        event = self.d.next_event()
        if event.type == X.SelectionRequest:
            log.debug("Selection request target=%s client=%s expected=%s",
                      self.d.get_atom_name(event.target), event.requestor.id & ~self.d.display.info.resource_id_mask,
                      getattr(self, "paste_client", None))
            prop = event.property or event.target
            success = self._serve(event.requestor, event.target, prop)
            event.requestor.send_event(protocol.event.SelectionNotify(
                time=event.time, requestor=event.requestor, selection=event.selection,
                target=event.target, property=prop if success else X.NONE), propagate=False)
            self.d.flush()
        elif event.type == X.PropertyNotify and event.state == X.PropertyDelete:
            key = (event.window.id, event.atom)
            transfer = self.transfers.get(key)
            if transfer:
                kind, fmt, value, offset, is_text, expires = transfer
                step = CHUNK_BYTES // (fmt // 8)
                chunk = value[offset:offset + step]
                event.window.change_property(event.atom, kind, fmt, chunk)
                self.d.flush()
                if len(chunk):
                    self.transfers[key] = (kind, fmt, value, offset + len(chunk), is_text, expires)
                else:
                    del self.transfers[key]
                    if self.pasting and is_text:
                        self.consumed = True
        return event

    def _serve(self, requestor, target, prop):
        if target == self.targets:
            requestor.change_property(prop, Xatom.ATOM, 32, list(self.data) + [self.targets])
            return True
        value = self.data.get(target)
        if value is None:
            return False
        kind, fmt, payload = value
        # Clipboard managers may fetch a new selection before the application.
        # Only the focused X client can acknowledge this text commit.
        is_text = (self.pasting and target in self.text_targets
                   and requestor.id & ~self.d.display.info.resource_id_mask == self.paste_client)
        size = len(payload) * (fmt // 8)
        if size <= CHUNK_BYTES:
            requestor.change_property(prop, kind, fmt, payload)
            if self.pasting and is_text:
                self.consumed = True
        else:
            requestor.change_attributes(event_mask=X.PropertyChangeMask)
            self.transfers[(requestor.id, prop)] = (kind, fmt, payload, 0, is_text, time.monotonic() + 30)
            requestor.change_property(prop, self.incr, 32, [size])
        return True

    def _read(self, target, deadline):
        self.window.delete_property(self.read_property)
        self.window.convert_selection(self.clipboard, target, self.read_property, X.CurrentTime)
        self.d.flush()
        while time.monotonic() < deadline:
            event = self._event(deadline)
            if (event is not None and event.type == X.SelectionNotify
                    and event.requestor.id == self.window.id and event.target == target):
                if not event.property:
                    raise RuntimeError("clipboard snapshot target refused")
                value = self.window.get_full_property(self.read_property, X.AnyPropertyType)
                self.window.delete_property(self.read_property)
                self.d.flush()
                if value is None:
                    raise RuntimeError("clipboard snapshot property missing")
                if value.property_type != self.incr:
                    if len(value.value) * (value.format // 8) > MAX_BYTES:
                        raise RuntimeError("clipboard snapshot too large")
                    return value.property_type, value.format, value.value
                break
        else:
            raise TimeoutError("clipboard snapshot timed out")
        result, kind, fmt, size = [], None, None, 0
        while time.monotonic() < deadline:
            event = self._event(deadline)
            if (event is None or event.type != X.PropertyNotify or event.window.id != self.window.id
                    or event.atom != self.read_property or event.state != X.PropertyNewValue):
                continue
            value = self.window.get_full_property(self.read_property, X.AnyPropertyType)
            if value is None or value.property_type == self.incr:
                continue
            self.window.delete_property(self.read_property)
            self.d.flush()
            if kind is None:
                kind, fmt = value.property_type, value.format
            if (kind, fmt) != (value.property_type, value.format):
                raise RuntimeError("clipboard snapshot format changed")
            if not len(value.value):
                return kind, fmt, b"".join(result) if fmt == 8 else [v for part in result for v in part]
            result.append(value.value)
            size += len(value.value) * (fmt // 8)
            if size > MAX_BYTES:
                raise RuntimeError("clipboard snapshot too large")
        raise TimeoutError("clipboard snapshot transfer timed out")

    def _snapshot(self):
        original = self.owner()
        if original == self.window.id:
            return dict(self.data)
        if not original:
            return {}
        deadline = time.monotonic() + 5
        _, fmt, targets = self._read(self.targets, deadline)
        if fmt != 32 or len(targets) > 128:
            raise RuntimeError("clipboard snapshot invalid targets")
        result, size, has_data = {}, 0, False
        ignored = {"TARGETS", "TIMESTAMP", "MULTIPLE", "SAVE_TARGETS", "DELETE", "INSERT_SELECTION", "INSERT_PROPERTY", "INCR", "TARGET_SIZES"}
        for target in dict.fromkeys(targets):
            name = self.d.get_atom_name(target)
            if name in ignored:
                continue
            has_data = True
            # Server-side drawable handles cannot outlive the previous owner.
            if name in {"PIXMAP", "BITMAP"}:
                continue
            kind, fmt, payload = self._read(target, deadline)
            if fmt not in (8, 16, 32):
                raise RuntimeError("clipboard snapshot unsupported format")
            size += len(payload) * (fmt // 8)
            if size > MAX_BYTES:
                raise RuntimeError("clipboard snapshot too large")
            result[target] = kind, fmt, payload
        if (not result and has_data) or self.owner() != original:
            raise RuntimeError("clipboard changed or cannot be preserved")
        return result

    def _commit(self, text):
        focus = self.d.get_input_focus().focus
        focused_id = getattr(focus, "id", 0)
        if focused_id <= 1:
            raise RuntimeError("no focused application for text commit")
        saved = self._snapshot()
        if getattr(self.d.get_input_focus().focus, "id", 0) != focused_id:
            raise RuntimeError("focus changed before text commit")
        utf8 = self.atom("UTF8_STRING")
        self.paste_client = focused_id & ~self.d.display.info.resource_id_mask
        self.text_targets = {self.atom(n) for n in ("UTF8_STRING", "text/plain;charset=utf-8", "text/plain", "TEXT")}
        self.data = {target: (utf8 if target == self.atom("TEXT") else target, 8, text.encode("utf-8"))
                     for target in self.text_targets}
        self.window.set_selection_owner(self.clipboard, X.CurrentTime)
        self.d.sync()
        self.pasting, self.consumed = True, False
        try:
            if self.owner() != self.window.id:
                raise RuntimeError("cannot own clipboard for text commit")
            shortcut = os.getenv("SELKIES_IME_PASTE_SHORTCUT", "ctrl+v")
            if shortcut not in {"ctrl+v", "ctrl+shift+v", "shift+Insert"}:
                raise ValueError("unsupported IME paste shortcut")
            subprocess.run(["xdotool", "key", "--clearmodifiers", shortcut],
                           env={**os.environ, "DISPLAY": self.display_name},
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=3, check=True)
            deadline = time.monotonic() + 8
            while not self.consumed and time.monotonic() < deadline:
                self._event(deadline)
                if self.owner() != self.window.id:
                    raise RuntimeError("clipboard replaced during text commit")
            if not self.consumed:
                raise TimeoutError("application did not request committed text")
        finally:
            self.pasting = False
            # Never overwrite a newer copy made by another application.
            if self.owner() == self.window.id:
                self.data = saved
                # Announce the restored formats to clients caching TARGETS.
                self.window.set_selection_owner(self.clipboard, X.CurrentTime)
                self.d.flush()
            else:
                self.data = {}

    def submit(self, text):
        future = Future()
        with self.state_lock:
            if self.closed:
                future.set_exception(RuntimeError("X display disconnected"))
            else:
                self.jobs.put((text, future))
        return future


async def paste_text(text):
    name = os.environ.get("DISPLAY", ":1")
    def get_bridge():
        with _bridge_lock:
            if name not in _bridges:
                _bridges[name] = SelectionOwner(name)
            return _bridges[name]
    bridge = await asyncio.to_thread(get_bridge)
    operation = asyncio.wrap_future(bridge.submit(text))
    try:
        return await asyncio.shield(operation)
    except asyncio.CancelledError:
        # Finish the selection transaction before connection key cleanup.
        await asyncio.gather(operation, return_exceptions=True)
        raise
